from pathlib import Path
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Image, PageBreak
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.colors import HexColor
from reportlab.lib.enums import TA_CENTER
from PIL import Image as PILImage
root=Path(__file__).resolve().parents[2];out=root/'output/pdf/Carribrary-Quick-Start-2.0.33.pdf'
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleC',fontName='Helvetica-Bold',fontSize=25,leading=29,textColor=HexColor('#173f47'),spaceAfter=14))
styles.add(ParagraphStyle(name='SectionC',fontName='Helvetica-Bold',fontSize=15,leading=20,textColor=HexColor('#173f47'),spaceBefore=10,spaceAfter=8))
styles.add(ParagraphStyle(name='BodyC',fontName='Helvetica',fontSize=10.5,leading=15,spaceAfter=9))
styles.add(ParagraphStyle(name='NoteC',parent=styles['BodyC'],backColor=HexColor('#edf5f6'),borderPadding=8,spaceBefore=6,spaceAfter=12))
styles.add(ParagraphStyle(name='CaptionC',fontName='Helvetica-Oblique',fontSize=8.5,leading=12,textColor=HexColor('#52676b'),spaceBefore=5,spaceAfter=8,alignment=TA_CENTER))
story=[]
def p(text,style='BodyC'):story.append(Paragraph(text.replace('–','-').replace('—','-'),styles[style]))
def title(text):p(text,'TitleC')
def section(text):p(text,'SectionC')
def img(name,maxw,maxh,caption):
 path=root/'home-library-native/server/wwwroot/guide'/name
 with PILImage.open(path) as im:w,h=im.size
 scale=min(maxw/w,maxh/h);story.append(Image(str(path),width=w*scale,height=h*scale));p(caption,'CaptionC')
def step(n,text):p(f'<b>{n}.</b> {text}')
def page():story.append(PageBreak())
title('Your first book, loan and backup')
p('Carribrary 2.0.33 | Illustrated quick start')
p('Use Carribrary without a phone companion, Google API key or public website. Pictures use fictional sample records. Your library name, colors and books may differ.')
section('1. Install and open')
p('<b>Windows:</b> open the installer, approve the Windows prompt, finish setup, then open Carribrary from the desktop or Start menu. Keep its normal program/data locations. No separate Node.js or .NET installation is required.')
p('<b>Linux:</b> install and launch the Flatpak in your software manager; keep it running for phones. <b>Raspberry Pi:</b> use the ARM64 DEB and included Pi guide; its service runs in the background.')
section('2. Choose where you will use it')
p('<b>At home only:</b> leave public sharing and remote access off. <b>At home and away:</b> on Windows open Start > Carribrary > Connection setup. Don’t have a hostname? Create a free hostname at <link href="https://www.duckdns.org/" color="#174e70">DuckDNS.org</link>, then return here. Sign in, choose a subdomain, and copy your full hostname and token into Connection setup. Select Save remote connection; Carribrary includes the automatic updater. Keep the token private. Existing hostname/updater users can skip DuckDNS. For public browser sharing, also select Set up public book-list sharing. Follow the router instructions. Test the paired phone with Wi-Fi off. DNS success alone does not prove remote access.')
img('catalog.png',420,240,'Success: your library opens to Catalog. Search, Add book, Check out and Return book are the everyday controls.')
page();title('Local administrator sign-in')
p('Carribrary requires its own administrator login on the server computer, even when Windows is signed in. Local dashboard sessions expire after 30 minutes idle, eight hours total, or a server restart.')
step(1,'On first open, use the private setup file shown on screen. On Windows choose <b>Start > Carribrary > Administrator access</b>, approve the Windows prompt, and select <b>Copy setup code</b>. This helper reads the code; it does not sign you in.')
step(2,'Paste the one-time code, choose a username and a password of 12-128 characters, and confirm the password.')
step(3,'Save the new recovery code privately, select <b>I have saved this code safely</b>, then open your library. Do not send codes to support.')
img('local-sign-in.png',160,285,'After initial setup, sign in here when opening the local administrator dashboard.')
p('<b>Existing paired Android and iPhone/browser companions keep their automatic access.</b> They do not need another username/password screen. Borrower accounts and private reading-vault passwords are separate.','NoteC')
p('Forgotten local password? Select <b>Recover local administrator access</b> with the saved recovery code. All local sessions end, a new recovery code is issued, and paired devices stay approved. Lost-code recovery requires protected server access and a stopped server; follow the full Help.')

page();title('Pair an optional phone')
p('The companion is for the librarian. Borrowers use the shared library page. You can skip this page and use the server on its own.')
step(1,'For this preview, download the Carribrary Android APK on the phone, open it in Files and tap Install. Public releases will use Google Play once the listing is available. Only the APK goes on the phone; source archives and private signing folders stay off it. If Android asks, allow this installation from the app opening the APK. For updates, install over the existing app without uninstalling.')
step(2,'Keep Carribrary running on the server computer. For the first local test, connect the phone to the same home Wi-Fi/network as that computer. Guest Wi-Fi may block devices from reaching each other.')
step(3,'On the computer open Setup & updates and note a local phone address, such as https://192.168.1.50:7443. Use the actual address shown for your home network. For access away from home, finish the hostname/router setup first and use your configured HTTPS hostname and phone port instead.')
step(4,'On the computer open Paired phones at the bottom of the admin catalog. Enter that address in Phone server address and select Create pairing QR. Do not use localhost on the phone; it means the phone itself.')
step(5,'Open the Android companion, enter a Phone name, select Scan pairing QR, and allow camera access. Scan the PRIVATE QR displayed on the computer. It works once and expires after five minutes; create another if needed.')
step(6,'If scanning fails, use Copy private pairing text on the computer, transfer it privately to your phone, paste the entire text into Pairing code (manual fallback), then select Pair phone. Never post this text or the QR publicly.')
step(7,'Success: the phone says Connected to library server and shows the same catalog. If Offline appears, check the address, shared network, server power and firewall access to the phone port, then refresh. For remote access test again with Wi-Fi off. Keep the server running.')
section('iPhone instead?')
p('Configure public HTTPS first. Open https://YOUR-HOST/companion/ in Safari, then Share > Add to Home Screen. Open the new icon. On the computer choose iPhone companion > Create private iPhone pairing code. Paste the code into the installed companion, name the device, then Pair this companion. Codes are single use for 10 minutes; browser administration lasts 30 days. No APK is needed.')
page();title('Add a physical book')
section('3. Your first book')
step(1,'Select <b>+ Add book</b>.')
step(2,'Scan the existing ISBN/EAN or type it. Manual entry remains available if a camera cannot scan.')
step(3,'Look up details if wanted. Check the title and author, then save. You can save without a cover.')
img('add-book.png',260,420,'Upper part of Add book. Scroll down in the form for the remaining fields and Save.')
p('<b>Success:</b> the book appears in Catalog with its own BK Copy ID. Separate physical copies receive separate Copy IDs. Custom labels are optional.','NoteC')
p('Not purchased yet? Use <b>Books to buy</b>, then confirm acquisition after purchase.')
page();title('Lend a book')
section('4. Add a borrower, if needed')
p('Open <b>Borrowers > Add borrower</b>. Enter a name and optional contact information, then save. Their name appears in the checkout selector. A sign-in account is optional for borrowing.')
section('5. Check out the physical copy')
step(1,'Select <b>Check out</b> and scan/enter ISBN/EAN or an optional Copy ID, or search manually.')
step(2,'Choose the physical copy if several available copies match. Select the borrower and an optional due date.')
step(3,'Confirm when the book is handed over. A request or hold reserves a copy; it does not start the loan.')
img('checkout.png',300,360,'Checkout using the existing book barcode or Copy ID. Review the copy and borrower before confirming.')
p('<b>Success:</b> the copy appears under <b>On loan</b>.','NoteC')
page();title('Return and back up')
section('6. Return the physical copy')
step(1,'Select <b>Return book</b>. Scan/enter ISBN/EAN or Copy ID.')
step(2,'Choose the matching checked-out copy if necessary, then confirm return.')
p('<b>Success:</b> the copy leaves On loan. Marking a reading entry finished does <b>not</b> return the physical book.','NoteC')
section('7. Create a complete backup')
step(1,'On the server open <b>Backups</b>. On Android open <b>More > Settings &amp; backups > Complete server data backup</b>.')
step(2,'Choose a backup password of <b>12-128 characters</b>, confirm it, and select <b>Create complete backup</b> (Android: Choose where to save).')
step(3,'Wait for the .carribrary-backup download to finish. Keep the file and password safely, preferably on a separate drive. The password cannot be reset.')
p('<b>No manual server stop or hidden-folder copying:</b> Carribrary briefly pauses changes, captures consistent database snapshots, then resumes automatically.','NoteC')
p('Includes current accounts, encrypted borrower vaults, pairing keys, keyring and saved settings. Borrowers still need their own private-list passphrases. Windows-protected keys/settings require the same Windows computer. Current data limit: 2 GB / 10,000 files; old backups, programs, external HTTPS/proxy certificates, OS tasks and environment-only settings are separate.')
p('<b>Library export (JSON)</b> is the smaller books-and-lending export. It excludes accounts, private vaults and server keys. Restore library export accepts that JSON only.')
p('<b>Complete recovery</b> uses the included offline utility with the server stopped. It verifies the archive and unpacks into a new folder without overwriting live data. Follow Full Help and RECOVERY-READ-ME.txt in that folder.')
p('<b>Borrowers:</b> export an encrypted personal backup after unlocking. The server-backup password cannot unlock a borrower private list.')
page();title('Update and recover safely')
section('8. Update without uninstalling')
p('<b>Before updating:</b> keep a complete backup. Version 2.0.33 retains library format 3 introduced in 2.0.31. Versions 2.0.30 and earlier cannot read it. If upgrading from a version without Complete backup, use its Windows recovery point or stopped-server data-folder backup instructions first.')
step(1,'Keep a private backup. Install the new server package over the existing installation.')
step(2,'Windows setup verifies program files and saves a protected pre-update recovery point, then checks startup and catalog access.')
step(3,'Update Android over the existing app without uninstalling or clearing data. The iPhone PWA updates with the server.')
section('If a Windows update causes trouble')
p('A failed compatible update attempts program recovery automatically. For a later problem, open <b>Start > Carribrary > Update and recovery</b> or the tray menu, select a prior version, then choose <b>Restore selected application</b> and confirm. This tool opens independently of the main server.')
p('<b>Current books, loans, account deletions, encrypted private lists and connection settings are kept.</b> The previous application is checked and restarted. A failed recovery attempts to put back the pre-attempt program; private safety archives remain.','NoteC')
p('This release explicitly supports program recovery within the <b>2.0.33 authentication cohort</b>. Older binaries remove mandatory local login, so they cannot be selected for automatic recovery even when the library format is the same. It does not restore an old database or cross incompatible data formats. Future schema/platform rollback is still planned. The tool requires a working Windows/PowerShell environment and administrator access; physical Windows integration testing is still needed.')
section('Historical private information')
p('Recovery points can contain historical information after an account is deleted. The owner removes them separately with <b>Update and recovery > Delete recovery points</b>, typing <b>DELETE RECOVERY POINTS</b>. This removes rollback ability; current live data remains. Ordinary account/backup cleanup does not remove protected points or external copies.')
p('No automatic retention pruning is enabled yet. Monitor disk space. Uninstall retains data, recovery points and their local trust registration. Do not share private snapshots, pairing codes, passwords, API keys or recovery codes.')
p('For focused instructions and the current online pictures, open <b>Help > Illustrated quick start</b> or search the full Help. Native offline phone Help provides the matching text instructions.')
page();title('Optional labels and copy numbers')
section('9. Choose how new numbers are assigned')
step(1,'Server: select <b>Copy numbering</b> in the footer. Android: <b>More > Settings &amp; backups > Copy labels &amp; numbering</b>.')
step(2,'Choose <b>Fill available gaps</b> (the existing default), or <b>Always use the next number</b>. Save your choice.')
p('Only future additions are affected. Existing books keep their numbers. Numbers linked to history stay protected in this release. The forward allocator remembers its high-water mark.')
section('10. Print labels for existing books')
step(1,'On the server select <b>Print copy labels</b>. On Android use <b>Copy labels &amp; numbering</b>. Search and select the books, up to 500 per batch.')
step(2,'Choose <b>Letter 30</b> (Avery 5160 geometry) or <b>A4 24</b> (63.5 x 33.9 mm). For a partial sheet, enter its first unused position, across each row then down.')
step(3,'Select <b>Print / Save PDF</b> in the browser, or <b>Save label PDF</b> on Android. Open the PDF in your print app.')
p('<b>Print at Actual size / 100%.</b> Turn browser headers and footers off. Test on plain paper against your label sheet first. Custom sheets and alignment offsets are planned.','NoteC')
section('What the QR identifies')
p('Each QR identifies the original physical copy permanently. It contains no account access or pairing secrets. If a deleted BK number is reused, its old QR cannot select the replacement book. Restoring a copy keeps its QR identity even if its displayed BK number changes.')
p('Old BK-only labels identify the current number assignment. Remove obsolete labels when reusing numbers. These are copy labels, separate from public sharing and private phone-pairing QR codes.')
p('<b>Labels stay optional.</b> Checkout and return still accept the existing ISBN/EAN barcode, a copy label, or manual search. A QR scan selects an eligible copy; a loan still needs confirmation.','NoteC')
def footer(canvas,doc):
 canvas.saveState();w,h=doc.pagesize;canvas.setStrokeColor(HexColor('#c9d8db'));canvas.line(44,38,w-44,38);canvas.setFillColor(HexColor('#52676b'));canvas.setFont('Helvetica',8);canvas.drawString(44,25,'Carribrary | Quick start | 2.0.33');canvas.drawRightString(w-44,25,str(doc.page));canvas.restoreState()
SimpleDocTemplate(str(out),pagesize=(612,792),leftMargin=44,rightMargin=44,topMargin=40,bottomMargin=52,title='Carribrary 2.0.33 Illustrated Quick Start',author='Carribrary').build(story,onFirstPage=footer,onLaterPages=footer)
print(out)
